/**
 * A centered row of topic pills: links where a topic has an address, else buttons. tone inverse: on a dark band
 * with an icon per topic; default: outlined.
 */
import { For, type JSX } from "solid-js";
import { Button, Group } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { urlOf } from "../utils";
import type { Topic } from "./topic-chips.types";

export type TopicChipsProps = {
  topics: Topic[];
  tone?: "default" | "inverse";
};

export function TopicChips({ topics, tone = "default" }: TopicChipsProps) {
  return (
    <Group gap="2" align="center" justify="center" class="flex-wrap" data-slot="hero-topics">
      <For each={topics ?? []}>{(topic) => (
        <>
          {((tone as string) === "inverse") ? (
            <Button
              href={urlOf(topic.href)}
              variant="ghost"
              size="sm"
              class="gap-2 text-background inset-ring-background/30 hover:bg-background/10"
            >
              {topic.icon ? (
                <LucideIcon name={topic.icon} size={16} />
              ) : null}
              {topic.name}
            </Button>
          ) : (
            <Button href={urlOf(topic.href)} variant="outline" size="sm">
              {topic.name}
            </Button>
          )}
        </>
      )}</For>
    </Group>
  );
}

